To classify a given sentence into one of the categories, you can use a machine learning approach. One way to do this is by training a classifier using a labeled dataset of sentences that have already been classified into the three categories.
Here is a sample code that demonstrates how to train and use a Naive Bayes classifier in C++ to classify sentences into the three categories:
```
#include <iostream>
#include <fstream>
#include <sstream>
#include <string>
#include <vector>
#include <map>
#include <cmath>
using namespace std;
// Define the categories
const string POLITICAL = "political";
const string BUSINESS = "business";
const string EDUCATION = "education";
// Define the classifier
class NaiveBayesClassifier {
public:
    void train(const vector<pair<string, string>>& trainingData);
    string classify(const string& sentence);
private:
    map<string, int> categoryCounts_;
    map<string, map<string, int>> wordCounts_;
    map<string, int> wordTotalCounts_;
    int totalSentences_;
};
// Train the classifier using the training data
void NaiveBayesClassifier::train(const vector<pair<string, string>>& trainingData) {
    // Count the number of sentences in each category
    for (const auto& data : trainingData) {
        categoryCounts_[data.second]++;
        totalSentences_++;
    }
    // Count the number of times each word appears in each category
    for (const auto& data : trainingData) {
        stringstream ss(data.first);
        string word;
        while (ss >> word) {
            wordCounts_[word][data.second]++;
            wordTotalCounts_[data.second]++;
        }
    }
}
// Classify a sentence into one of the categories
string NaiveBayesClassifier::classify(const string& sentence) {
    // Calculate the probability of the sentence belonging to each category
    map<string, double> probabilities;
    stringstream ss(sentence);
    string word;
    while (ss >> word) {
        for (const auto& category : {POLITICAL, BUSINESS, EDUCATION}) {
            double wordCount = wordCounts_[word][category];
            double wordTotalCount = wordTotalCounts_[category];
            double categoryCount = categoryCounts_[category];
            double probability = (wordCount + 1) / (wordTotalCount + wordCounts_.size());
            probabilities[category] += log(probability);
        }
    }
    for (auto& p : probabilities) {
        p.second += log(categoryCounts_[p.first] / (double)totalSentences_);
    }
    // Return the category with the highest probability
    string category;
    double maxProbability = -INFINITY;
    for (const auto& p : probabilities) {
        if (p.second > maxProbability) {
            maxProbability = p.second;
            category = p.first;
        }
    }
    return category;
}
int main() {
    // Define the training data
    vector<pair<string, string>> trainingData = {
        {"The government is proposing a new tax bill.", POLITICAL},
        {"Apple's stock price has reached an all-time high.", BUSINESS},
        {"The University of Texas is researching more effective ways to run online classes.", EDUCATION},
        {"The president is meeting with foreign leaders to discuss trade agreements.", POLITICAL},
        {"Amazon is expanding its operations in Europe.", BUSINESS},
        {"Harvard University is offering new courses in artificial intelligence.", EDUCATION},
        {"The Senate has passed a new healthcare bill.", POLITICAL},
        {"Google is investing in renewable energy.", BUSINESS},
        {"Stanford University is hosting a conference on machine learning.", EDUCATION}
    };
    // Train the classifier
    NaiveBayesClassifier classifier;
    classifier.train(trainingData);
    // Classify a new sentence
    string sentence = "The University of Texas is researching more effective ways to run online classes.";
    string category = classifier.classify(sentence);
    cout << "The sentence \"" << sentence << "\" belongs to the \"" << category << "\" category." << endl;
    return 0;
}
```
In this code, the `NaiveBayesClassifier` class defines a Naive Bayes classifier that can be trained using a vector of pairs, where each pair contains a sentence and its corresponding category. The `train` method counts the number of sentences in each category and the number of times each word appears in each category. The `classify` method calculates the probability of the sentence belonging to each category using the Naive Bayes formula and returns the category with the highest probability.
In the `main` function, a vector of training data is defined, and the classifier is trained using this data. Then, a new sentence is classified using the `classify` method, and the resulting category is printed to the console. In this example, the sentence "The University of Texas is researching more effective ways to run online classes." is classified as belonging to the education category.

