        string nextFourDigits = random.Next(1000, 9999).ToString();

        // Generate the last four digits of the social security number based on the individual's eligibility
        string lastFourDigits = "0000";
        if (isCitizen && isEmployed)
        {
            lastFourDigits = random.Next(1000, 9999).ToString();
        }

        // Combine the parts of the social security number and return the result
        string ssn = $"{firstThreeDigits}-{nextTwoDigits}-{nextFourDigits}-{lastFourDigits}";
        return ssn;
    }
}
```
This code generates a social security number based on the individual's date of birth, citizenship status, and employment status. It uses a combination of the year and month of birth, a random number, and a final set of digits based on the individual's eligibility to generate a unique and legally compliant social security number. 
