binary_search <- function(x, key) {
  low <- 1
  high <- length(x)

  while (low <= high) {
    mid <- floor((low + high) / 2)
    if (x[mid] < key) {
      low <- mid + 1
    } else if (x[mid] > key) {
      high <- mid - 1
    } else {
      return(TRUE)
    }
  }
  return(FALSE)
}

