    // Initialize the intuition score
    intuitionScore := 0
    // Loop through the suspects
    for i := 0; i < len(suspects); i++ {
        // Initialize the suspect score
        suspectScore := 0
        // Loop through the clues
        for j := 0; j < len(clues); j++ {
            // Check if the suspect matches the clue
            if (suspects[i] == "John" && clues[j] == "The suspect was wearing a red shirt.") || (suspects[i] == "Sarah" && clues[j] == "The suspect has a tattoo on their left arm.") || (suspects[i] == "David" && clues[j] == "The suspect has a scar on their forehead.") {
                // Increase the suspect score
                suspectScore++
            }
        }
        // Loop through the evidence
        for k := 0; k < len(evidence); k++ {
