        double[] iceBathSensoryEvaluation = { 5, 6, 7 };
        // Calculate the overall score for each cooling method
        double liquidNitrogenScore = CalculateOverallScore(liquidNitrogenFirmness, liquidNitrogenViscosity, liquidNitrogenpH, liquidNitrogenMicrobialActivity, liquidNitrogenSensoryEvaluation, firmnessWeight, viscosityWeight, pHWeight, microbialActivityWeight, sensoryEvaluationWeight);
        double dryIceScore = CalculateOverallScore(dryIceFirmness, dryIceViscosity, dryIcepH, dryIceMicrobialActivity, dryIceSensoryEvaluation, firmnessWeight, viscosityWeight, pHWeight, microbialActivityWeight, sensoryEvaluationWeight);
        double iceBathScore = CalculateOverallScore(iceBathFirmness, iceBathViscosity, iceBathpH, iceBathMicrobialActivity, iceBathSensoryEvaluation, firmnessWeight, viscosityWeight, pHWeight, microbialActivityWeight, sensoryEvaluationWeight);
        // Print the overall score for each cooling method
        Console.WriteLine("Overall score for liquid nitrogen: " + liquidNitrogenScore);
        Console.WriteLine("Overall score for dry ice: " + dryIceScore);
        Console.WriteLine("Overall score for ice bath: " + iceBathScore);
    }
    static double CalculateOverallScore(double[] firmnessValues, double[] viscosityValues, double[] pHValues, double[] microbialActivityValues, double[] sensoryEvaluationValues, double firmnessWeight, double viscosityWeight, double pHWeight, double microbialActivityWeight, double sensoryEvaluationWeight)
    {
        // Calculate the weighted sum of the measured properties
        double firmnessSum = 0;
        double viscositySum = 0;
        double pHSum = 0;
        double microbialActivitySum = 0;
        for (int i = 0; i < firmnessValues.Length; i++)
        {
            firmnessSum += firmnessValues[i];
            viscositySum += viscosityValues[i];
            pHSum += pHValues[i];
            microbialActivitySum += microbialActivityValues[i];
        }
        double weightedFirmness = firmnessSum / firmnessValues.Length * firmnessWeight;
        double weightedViscosity = viscositySum / viscosityValues.Length * viscosityWeight;
        double weightedpH = pHSum / pHValues.Length * pHWeight;
        double weightedMicrobialActivity = microbialActivitySum / microbialActivityValues.Length * microbialActivityWeight;
        // Calculate the weighted sum of the sensory evaluation results
        double sensoryEvaluationSum = 0;
        for (int i = 0; i < sensoryEvaluationValues.Length; i++)
        {
            sensoryEvaluationSum += sensoryEvaluationValues[i];
        }
        double weightedSensoryEvaluation = sensoryEvaluationSum / sensoryEvaluationValues.Length * sensoryEvaluationWeight;
        // Calculate the overall score
        double overallScore = weightedFirmness + weightedViscosity + weightedpH + weightedMicrobialActivity + weightedSensoryEvaluation;
        return overallScore;
    }
}
```
