$data = json_decode($data, true);
// Extract necessary data
$countries = array();
$confirmed = array();
$deaths = array();
$recovered = array();
$active = array();
$death_rate = array();
foreach ($data['Countries'] as $key => $value) {
    $countries[] = $value['Country'];
    $confirmed[] = $value['TotalConfirmed'];
    $deaths[] = $value['TotalDeaths'];
    $recovered[] = $value['TotalRecovered'];
    $active[] = $value['TotalConfirmed'] - $value['TotalRecovered'] - $value['TotalDeaths'];
    $death_rate[] = round($value['TotalDeaths'] / $value['TotalConfirmed'] * 100, 2);
}
// Create bar chart using GD library
$width = 1000;
