$confirmed_color = imagecolorallocate($image, 0, 128, 0);
$active_color = imagecolorallocate($image, 255, 165, 0);
$recovered_color = imagecolorallocate($image, 0, 191, 255);
$death_color = imagecolorallocate($image, 255, 0, 0);
$font_color = imagecolorallocate($image, 0, 0, 0);
$max_value = max(max($confirmed), max($deaths), max($recovered), max($active));
$scale = ($height - 2 * $padding) / $max_value;
for ($i = 0; $i < count($countries); $i++) {
    $x1 = $padding + $i * ($bar_width + 10);
    $y1 = $height - $padding;
