    $x1 = $padding + $i * ($bar_width + 10);
    $y1 = $height - $padding - $recovered[$i] * $scale;
    $x2 = $x1 + $bar_width;
    $y2 = $height - $padding - ($recovered[$i] + $death_rate[$i] / 100 * $confirmed[$i]) * $scale;
    imagefilledrectangle($image, $x1, $y1, $x2, $y2, $recovered_color);
    $x1 = $padding + $i * ($bar_width + 10);
    $y1 = $height - $padding - ($recovered[$i] + $death_rate[$i] / 100 * $confirmed[$i]) * $scale;
    $x2 = $x1 + $bar_width;
    $y2 = $height - $padding - $deaths[$i] * $scale;
    imagefilledrectangle($image, $x1, $y1, $x2, $y2, $death_color);
    imagestring($image, 5, $x1, $height - $padding + 10, $countries[$i], $font_color);
}
imagefilledrectangle($image, $width - $legend_padding, $padding, $width - 50, $padding + 20, $confirmed_color);
imagefilledrectangle($image, $width - $legend_padding, $padding + 30, $width - 50, $padding + 50, $active_color);
