Implementing a scalable, self-configuring, and self-healing mesh network in a home using Go programming language can be achieved using several libraries and frameworks such as libp2p, gRPC, and Protocol Buffers. Here is a sample code that illustrates how to create a mesh network topology, establish node communication, handle data transmission and routing using the libp2p library:
```go
package main
import (
	"context"
	"fmt"
	"github.com/libp2p/go-libp2p"
	"github.com/libp2p/go-libp2p-core/host"
	"github.com/libp2p/go-libp2p-core/network"
	"github.com/libp2p/go-libp2p-core/protocol"
	"github.com/libp2p/go-libp2p-core/routing"
	"github.com/libp2p/go-libp2p-kad-dht"
	"github.com/multiformats/go-multiaddr"
	"log"
	"os"
	"os/signal"
	"syscall"
)
func main() {
	ctx := context.Background()
	// create a new libp2p host
	host, err := libp2p.New(ctx)
	if err != nil {
		log.Fatal(err)
	}
	// create a new DHT
	dht, err := dht.New(ctx, host)
	if err != nil {
		log.Fatal(err)
	}
	// bootstrap the DHT
	if err = dht.Bootstrap(ctx); err != nil {
		log.Fatal(err)
	}
	// set up a stream handler to receive messages
	host.SetStreamHandler(protocol.ID("/mesh"), func(stream network.Stream) {
		// read the incoming message
		buf := make([]byte, 1024)
		n, err := stream.Read(buf)
		if err != nil {
			log.Println(err)
			return
		}
		log.Printf("Received message: %s", string(buf[:n]))
		// close the stream
		stream.Close()
	})
	// create a new multiaddress for the host
	addr, err := multiaddr.NewMultiaddr(fmt.Sprintf("/ipfs/%s", host.ID().Pretty()))
	if err != nil {
		log.Fatal(err)
	}
	// announce the host on the DHT
	if err = dht.Provide(ctx, addr, true); err != nil {
		log.Fatal(err)
	}
	// set up a signal handler to gracefully shut down the host
	c := make(chan os.Signal, 1)
	signal.Notify(c, os.Interrupt, syscall.SIGTERM)
	go func() {
		<-c
		if err := host.Close(); err != nil {
			log.Println(err)
		}
	}()
	// create a new routing table
	rt := dht.RoutingTable()
	// get the closest peers to the host
	peers, err := rt.NearestPeers(ctx, host.ID(), 10)
	if err != nil {
		log.Fatal(err)
	}
	// connect to the closest peers
	for _, peer := range peers {
		if peer == host.ID() {
			continue
		}
		pi, err := dht.FindPeer(ctx, peer)
		if err != nil {
			log.Println(err)
			continue
		}
		if err = host.Connect(ctx, pi); err != nil {
			log.Println(err)
			continue
		}
	}
	// create a new message
	msg := []byte("Hello, world!")
	// broadcast the message to all connected peers
	for _, peer := range host.Network().Peers() {
		if peer == host.ID() {
			continue
		}
		stream, err := host.NewStream(ctx, peer, protocol.ID("/mesh"))
		if err != nil {
			log.Println(err)
			continue
		}
		if _, err = stream.Write(msg); err != nil {
			log.Println(err)
			continue
		}
		stream.Close()
	}
	// wait for a signal to shut down the host
	<-c
	if err := host.Close(); err != nil {
		log.Println(err)
	}
}
```
This code creates a new libp2p host and DHT, sets up a stream handler to receive messages, announces the host on the DHT, connects to the closest peers, and broadcasts a message to all connected peers.
